const base=0x0800;const lines=[];let run=null;const rows=[];for(let p=0;p<bytes.length;p+=256){const s=bytes.slice(p,p+256);let nz=0;const set=new Set();for(const b of s){if(b)nz++;set.add(b);}rows.push({a:base+p,nz,d:set.size});}
let cur=null;for(const r of rows){const cls=r.nz===0?'zero':(r.d<=8?'sparse':(r.d>=100?'dense':'mixed'));if(cur&&cur.cls===cls)cur.end=r.a+255;else{if(cur)lines.push(cur);cur={cls,start:r.a,end:r.a+255};}}if(cur)lines.push(cur);
return {kind:'text',lines:lines.map(l=>'$'+l.start.toString(16).toUpperCase().padStart(4,'0')+'-$'+l.end.toString(16).toUpperCase().padStart(4,'0')+'  '+l.cls)};
